option.value:
plugins {
    id 'java-library'
    id('com.gradleup.shadow') version '9.3.1' apply false
    id('com.vanniktech.maven.publish') version '0.36.0' apply false
}

ext {
    publishableModules = [
            'kash-helper-common',
            'kash-helper-paper',
            'kash-helper-jda'
    ] as Set
}

// Maven Central rejects SNAPSHOTs for release publishing: strip suffix when central tasks run.
def configuredVersion = (findProperty('projectVersion') ?: '0.0.3').toString()
def centralPublishRequested = gradle.startParameter.taskNames.any {
    def task = it.toLowerCase()
    task.contains('publishandreleasetomavencentral') || task.contains('publishtomavencentral')
}
def effectiveVersion = (centralPublishRequested && configuredVersion.endsWith('-SNAPSHOT'))
        ? configuredVersion - '-SNAPSHOT'
        : configuredVersion

allprojects {
    group = 'xyz.imrine'
    version = effectiveVersion

    repositories {
        mavenCentral()
        mavenLocal()
    }
}

subprojects {
    apply plugin: 'java-library'
    apply plugin: 'com.gradleup.shadow'

    java {
        toolchain {
            languageVersion = JavaLanguageVersion.of(21)
        }
        withSourcesJar()
    }

    tasks.withType(JavaCompile).configureEach {
        options.encoding = 'UTF-8'
        options.release = 21
    }

    tasks.test {
        useJUnitPlatform()
    }

    tasks.jar {
        archiveClassifier.set('plain')
    }

    tasks.shadowJar {
        archiveClassifier.set('')
        mergeServiceFiles()
    }

    tasks.withType(GenerateModuleMetadata).configureEach {
        enabled = false
    }

    if (rootProject.publishableModules.contains(project.name)) {
        apply plugin: 'com.vanniktech.maven.publish'
        apply plugin: 'signing'

        mavenPublishing {
            coordinates(project.group.toString(), project.name, project.version.toString())
            publishToMavenCentral(true)
            signAllPublications()

            pom {
                name = "KashHelper ${project.name - 'kash-helper-'}".trim()
                description = "${project.name} module for KashHelper"
                url = 'https://github.com/Ibramsou/KashHelper'
                licenses {
                    license {
                        name = 'The Apache License, Version 2.0'
                        url = 'https://www.apache.org/licenses/LICENSE-2.0.txt'
                    }
                }
                developers {
                    developer {
                        id = 'Bramsou'
                        name = 'Ibrahim'
                        email = 'braimsou@gmail.com'
                    }
                }
                scm {
                    url = 'https://github.com/Ibramsou/KashHelper'
                    connection = 'scm:git:git://github.com/Ibramsou/KashHelper.git'
                    developerConnection = 'scm:git:ssh://github.com/Ibramsou/KashHelper.git'
                }
            }
        }

        // Support key-file based signing setup from ~/.gradle/gradle.properties
        final signingKeyFile = (findProperty('signingInMemoryKeyFile') ?: System.getenv('SIGNING_IN_MEMORY_KEY_FILE'))?.toString()
        final signingKeyPassword = (findProperty('signingInMemoryKeyPassword') ?: System.getenv('SIGNING_IN_MEMORY_KEY_PASSWORD'))?.toString()
        if (signingKeyFile && file(signingKeyFile).exists()) {
            signing {
                // Keys are configured here; publication selection is handled by signAllPublications().
                useInMemoryPgpKeys(file(signingKeyFile).text, signingKeyPassword)
            }
        }
    }
}

