tasks.register('testsQuick') {
    group = 'verification'
    description = 'Runs quick persistence checks and compiles the Paper example.'
    dependsOn(':kash-helper-common:persistenceSmokeTests')
    dependsOn(':kash-helper-paper:example:compileJava')
}

tasks.register('testsAll') {
    group = 'verification'
    description = 'Runs test tasks for key modules.'
    dependsOn(':kash-helper-common:test')
    dependsOn(':kash-helper-paper:test')
    dependsOn(':kash-helper-jda:test')
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlob;
import fr.ibrakash.helper.persistence.entity.PersistedBlobKind;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobTier;
import fr.ibrakash.helper.persistence.entity.PersistedColumn;
import fr.ibrakash.helper.persistence.entity.PersistedEmbedded;
import fr.ibrakash.helper.persistence.entity.PersistedEntity;
import fr.ibrakash.helper.persistence.entity.PersistedId;
import fr.ibrakash.helper.persistence.entity.PersistedIndex;
import fr.ibrakash.helper.persistence.entity.PersistedIndexes;
import fr.ibrakash.helper.persistence.entity.PersistedRelation;
import fr.ibrakash.helper.persistence.entity.PersistedJson;
import fr.ibrakash.helper.persistence.entity.PersistedJsonMode;
import fr.ibrakash.helper.persistence.entity.PersistedRank;
import fr.ibrakash.helper.persistence.query.SortClause;
import fr.ibrakash.helper.persistence.query.SortDirection;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

public final class EntityModel<T, ID> {

    private static final int MAX_INDEX_NAME_LENGTH = 63;

    public record Column(
            Field rootField,
            Field leafField,
            String name,
            Class<?> type,
            boolean nullable,
            String defaultValue,
            int length,
            boolean id,
            VarHandle rootHandle,
            VarHandle leafHandle,
            Constructor<?> rootConstructor
    ) {}

    public record IndexDef(String name, List<String> columns, boolean unique) {}

    public record RelationColumn(Field field, String name, Class<?> type, int length, VarHandle handle) {}

    public record RelationDef(
            Field field,
            VarHandle collectionHandle,
            Constructor<?> elementConstructor,
            String table,
            String joinColumn,
            String valueColumn,
            String orderColumn,
            Class<?> elementType,
            boolean simple,
            List<RelationColumn> objectColumns
    ) {}

    public record BlobDef(
            Field field,
            VarHandle handle,
            String name,
            Class<?> type,
            boolean nullable,
            PersistedBlobKind kind,
            PersistedBlobTier tier,
            int length,
            Class<? extends PersistedBlobSerializer<?>> serializerClass,
            PersistedBlobSerializer<Object> serializer,
            Constructor<?> binaryStorageConstructor
    ) {}

    public record RankDef(
            Field field,
            VarHandle handle,
            String name,
            List<SortClause> sorts,
            boolean loadOnDeserialize
    ) {}

    private final Class<T> entityType;
    private final Class<ID> idType;
    private final String namespace;
    private final Column idColumn;
    private final List<Column> columns;
    private final List<IndexDef> indexes;
    private final List<RelationDef> relations;
    private final List<BlobDef> blobs;
    private final Constructor<T> entityConstructor;
    private final PersistedJsonMode jsonMode;
    private final List<RankDef> ranks;

    private EntityModel(Class<T> entityType,
                        Class<ID> idType,
                        String namespace,
                        Column idColumn,
                        List<Column> columns,
                        List<IndexDef> indexes,
                        List<RelationDef> relations,
                        List<BlobDef> blobs,
                        Constructor<T> entityConstructor,
                        PersistedJsonMode jsonMode,
                        List<RankDef> ranks) {
        this.entityType = entityType;
        this.idType = idType;
        this.namespace = namespace;
        this.idColumn = idColumn;
        this.columns = columns;
        this.indexes = indexes;
        this.relations = relations;
        this.blobs = blobs;
        this.entityConstructor = entityConstructor;
        this.jsonMode = jsonMode;
        this.ranks = ranks;
    }

    public static <T, ID> EntityModel<T, ID> from(Class<T> entityType, Class<ID> idType) {
        Field idField = null;
        List<Column> cols = new ArrayList<>();
        List<RelationDef> relations = new ArrayList<>();
        List<BlobDef> blobs = new ArrayList<>();
        List<RankDef> ranks = new ArrayList<>();

        for (Field field : entityType.getDeclaredFields()) {
            field.setAccessible(true);

            PersistedId id = field.getAnnotation(PersistedId.class);
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            PersistedEmbedded embedded = field.getAnnotation(PersistedEmbedded.class);
            PersistedColumn col = field.getAnnotation(PersistedColumn.class);
            PersistedBlob blob = field.getAnnotation(PersistedBlob.class);
            PersistedRank rank = field.getAnnotation(PersistedRank.class);

            if (id != null) {
                if (idField != null) {
                    throw new IllegalArgumentException("Multiple @PersistedId fields in " + entityType.getName());
                }
                String name = id.value().isBlank() ? snake(field.getName()) : id.value();
                idField = field;
                cols.add(new Column(null, field, name, field.getType(), false, "", 36, true,
                        null, varHandle(field), null));
                continue;
            }

            if (relation != null) {
                continue;
            }

            if (rank != null) {
                int mod = field.getModifiers();
                if (!java.lang.reflect.Modifier.isTransient(mod)) {
                    throw new IllegalArgumentException("@PersistedRank field must be transient: " + entityType.getName() + "#" + field.getName());
                }
                ranks.add(new RankDef(field, varHandle(field), field.getName(), List.of(), rank.load_on_deserialize()));
                continue;
            }

            if (embedded != null) {
                cols.addAll(parseEmbedded(field, embedded));
                continue;
            }

            if (blob != null) {
                blobs.add(parseBlob(field, blob));
                continue;
            }

            if (col == null) {
                int mod = field.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || field.isSynthetic()) {
                    continue;
                }
                cols.add(new Column(null, field, snake(field.getName()), field.getType(), true, "", 255, false,
                        null, varHandle(field), null));
            } else {
                String name = col.value().isBlank() ? snake(field.getName()) : col.value();
                cols.add(new Column(null, field, name, field.getType(), col.nullable(), col.defaultValue(), col.length(), false,
                        null, varHandle(field), null));
            }
        }

        if (idField == null) {
            throw new IllegalArgumentException("Missing @PersistedId field in " + entityType.getName());
        }

        for (Field field : entityType.getDeclaredFields()) {
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            if (relation == null) continue;
            field.setAccessible(true);
            relations.add(parseRelation(field, relation, idField));
        }

        Column idCol = cols.stream().filter(Column::id).findFirst().orElseThrow();
        List<Column> nonId = cols.stream().filter(c -> !c.id()).toList();

        PersistedEntity entityAnn = entityType.getAnnotation(PersistedEntity.class);
        String namespace = entityAnn != null && !entityAnn.value().isBlank()
                ? entityAnn.value()
                : snake(entityType.getSimpleName());

        List<IndexDef> indexes = parseIndexes(entityType);

        List<SortClause> defaultSort = List.of(new SortClause(idCol.name(), SortDirection.ASC));
        List<RankDef> resolvedRanks = new ArrayList<>(ranks.size());
        for (RankDef rank : ranks) {
            PersistedRank ann = rank.field().getAnnotation(PersistedRank.class);
            List<SortClause> parsed = parseSortClauses(ann.sort_columns(), idCol, nonId);
            if (parsed.isEmpty()) parsed = defaultSort;
            resolvedRanks.add(new RankDef(rank.field(), rank.handle(), rank.name(), parsed, rank.loadOnDeserialize()));
        }

        PersistedJson persistedJson = entityType.getAnnotation(PersistedJson.class);
        PersistedJsonMode configured = persistedJson == null ? PersistedJsonMode.AUTO : persistedJson.mode();
        PersistedJsonMode jsonMode = configured == PersistedJsonMode.AUTO
                ? (resolvedRanks.isEmpty() ? PersistedJsonMode.LOAD_ON_DEMAND : PersistedJsonMode.LOAD_ALL)
                : configured;

        return new EntityModel<>(
                entityType,
                idType,
                namespace,
                idCol,
                nonId,
                indexes,
                relations,
                blobs,
                constructor(entityType),
                jsonMode,
                List.copyOf(resolvedRanks)
        );
    }

    private static List<Column> parseEmbedded(Field rootField, PersistedEmbedded embedded) {
        List<Column> out = new ArrayList<>();
        String prefix = embedded.prefix().isBlank() ? snake(rootField.getName()) + "_" : embedded.prefix();
        VarHandle rootHandle = varHandle(rootField);
        Constructor<?> rootConstructor = constructor(rootField.getType());

        for (Field nested : rootField.getType().getDeclaredFields()) {
            nested.setAccessible(true);
            int mod = nested.getModifiers();
            if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                continue;
            }

            PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
            String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
            boolean nullable = nestedCol == null || nestedCol.nullable();
            String defaultValue = nestedCol == null ? "" : nestedCol.defaultValue();
            int length = nestedCol == null ? 255 : nestedCol.length();
            out.add(new Column(rootField, nested, prefix + baseName, nested.getType(), nullable, defaultValue, length, false,
                    rootHandle, varHandle(nested), rootConstructor));
        }

        return out;
    }

    private static RelationDef parseRelation(Field field, PersistedRelation relation, Field idField) {
        if (!(field.getGenericType() instanceof ParameterizedType pt)) {
            throw new IllegalArgumentException("@PersistedRelation field must be parameterized: " + field.getName());
        }

        Type raw = pt.getRawType();
        if (!(raw instanceof Class<?> rawClass) || !java.util.Collection.class.isAssignableFrom(rawClass)) {
            throw new IllegalArgumentException("@PersistedRelation currently supports Collection/List/Set only: " + field.getName());
        }

        Type elementTypeArg = pt.getActualTypeArguments()[0];
        if (!(elementTypeArg instanceof Class<?> elementType)) {
            throw new IllegalArgumentException("Unsupported @PersistedRelation element type on " + field.getName());
        }

        String joinColumn = relation.joinColumn().isBlank()
                ? snake(idField.getName())
                : relation.joinColumn();
        String valueColumn = relation.valueColumn();
        String orderColumn = relation.orderColumn();

        boolean simple = EntityTypeMapper.isSupportedType(elementType);
        if (simple && valueColumn.isBlank()) {
            throw new IllegalArgumentException("@PersistedRelation valueColumn is required for simple element type on field " + field.getName());
        }

        List<RelationColumn> objectColumns = new ArrayList<>();
        Constructor<?> elementConstructor = null;
        if (!simple) {
            if (!valueColumn.isBlank()) {
                throw new IllegalArgumentException("@PersistedRelation valueColumn must be empty for object element type on field " + field.getName());
            }
            String prefix = relation.prefix().isBlank() ? snake(field.getName()) + "_" : relation.prefix();
            elementConstructor = constructor(elementType);
            for (Field nested : elementType.getDeclaredFields()) {
                nested.setAccessible(true);
                int mod = nested.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                    continue;
                }
                PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
                String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
                int length = nestedCol == null ? 255 : nestedCol.length();
                objectColumns.add(new RelationColumn(nested, prefix + baseName, nested.getType(), length, varHandle(nested)));
            }

            if (objectColumns.isEmpty()) {
                throw new IllegalArgumentException("@PersistedRelation object field has no serializable nested fields: " + field.getName());
            }
        }

        return new RelationDef(field, varHandle(field), elementConstructor, relation.table(), joinColumn, valueColumn, orderColumn,
                elementType, simple, objectColumns);
    }

    private static List<IndexDef> parseIndexes(Class<?> type) {
        List<IndexDef> out = new ArrayList<>();

        PersistedIndex one = type.getAnnotation(PersistedIndex.class);
        if (one != null) {
            out.add(toIndex(one, type.getSimpleName()));
        }

        PersistedIndexes many = type.getAnnotation(PersistedIndexes.class);
        if (many != null) {
            for (PersistedIndex index : many.value()) {
                out.add(toIndex(index, type.getSimpleName()));
            }
        }

        return out;
    }

    private static IndexDef toIndex(PersistedIndex ann, String entityName) {
        if (ann.columns().length == 0) {
            throw new IllegalArgumentException("@PersistedIndex on " + entityName + " has no columns");
        }
        String desired = ann.name().isBlank()
                ? "idx_" + snake(entityName) + "_" + String.join("_", ann.columns())
                : ann.name();
        return new IndexDef(shortenIndexName(desired), List.of(ann.columns()), ann.unique());
    }

    private static String shortenIndexName(String value) {
        String normalized = value.toLowerCase(Locale.ROOT);
        if (normalized.length() <= MAX_INDEX_NAME_LENGTH) {
            return normalized;
        }

        String hash = String.format(Locale.ROOT, "%08x", normalized.hashCode());
        int prefixLength = MAX_INDEX_NAME_LENGTH - 9;
        return normalized.substring(0, prefixLength) + "_" + hash;
    }

    private static String snake(String input) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c) && i > 0) {
                out.append('_');
            }
            out.append(Character.toLowerCase(c));
        }
        return out.toString();
    }

    private static VarHandle varHandle(Field field) {
        try {
            return MethodHandles.privateLookupIn(field.getDeclaringClass(), MethodHandles.lookup()).unreflectVarHandle(field);
        } catch (IllegalAccessException e) {
            throw new IllegalArgumentException("Unable to create VarHandle for field " + field.getDeclaringClass().getName() + "#" + field.getName(), e);
        }
    }

    @SuppressWarnings("unchecked")
    private static <V> Constructor<V> constructor(Class<?> type) {
        try {
            Constructor<V> constructor = (Constructor<V>) type.getDeclaredConstructor();
            constructor.setAccessible(true);
            return constructor;
        } catch (NoSuchMethodException e) {
            throw new IllegalArgumentException("Type requires a no-arg constructor: " + type.getName(), e);
        }
    }

    private static BlobDef parseBlob(Field field, PersistedBlob blob) {
        String name = blob.value().isBlank() ? snake(field.getName()) : blob.value();

        Class<? extends PersistedBlobSerializer<?>> serializerClass = blob.serializer();
        PersistedBlobSerializer<Object> serializer = PersistedBlobSerializers.resolve(field.getType(), field.getGenericType(), serializerClass);

        boolean hasExplicitSerializer = serializerClass != null && serializerClass != NoPersistedBlobSerializer.class;
        boolean binaryStorage = fr.ibrakash.helper.binary.BinaryStorage.class.isAssignableFrom(field.getType());
        boolean rawBytes = field.getType() == byte[].class;

        if (!binaryStorage && !rawBytes && serializer == null) {
            throw new IllegalArgumentException("@PersistedBlob field requires a serializer or BinaryStorage type: " + field.getName());
        }

        Constructor<?> storageCtor = null;
        if (binaryStorage) {
            storageCtor = constructor(field.getType());
            if (!hasExplicitSerializer && serializer == null) {
                serializer = null; // BinaryStorage handles serialization itself.
            }
        }

        return new BlobDef(
                field,
                varHandle(field),
                name,
                field.getType(),
                blob.nullable(),
                blob.kind(),
                blob.blobTier(),
                blob.length(),
                serializerClass,
                serializer,
                storageCtor
        );
    }

    private static List<SortClause> parseSortClauses(String[] values, Column idColumn, List<Column> columns) {
        if (values == null || values.length == 0) {
            return List.of();
        }
        List<SortClause> out = new ArrayList<>(values.length);
        for (String raw : values) {
            if (raw == null || raw.isBlank()) continue;
            String spec = raw.trim();
            String[] parts = spec.split("\\s+");
            String field = parts[0];
            SortDirection direction = SortDirection.ASC;
            if (parts.length > 1 && parts[1].equalsIgnoreCase("DESC")) {
                direction = SortDirection.DESC;
            }
            String resolved = resolveSortColumnName(field, idColumn, columns);
            out.add(new SortClause(resolved, direction));
        }
        return out;
    }

    private static String resolveSortColumnName(String fieldOrColumn, Column idColumn, List<Column> columns) {
        if (matchesColumn(idColumn, fieldOrColumn)) {
            return idColumn.name();
        }
        for (Column column : columns) {
            if (matchesColumn(column, fieldOrColumn)) {
                return column.name();
            }
        }
        throw new IllegalArgumentException("Unknown rank/sort field '" + fieldOrColumn + "'");
    }

    private static boolean matchesColumn(Column column, String fieldOrColumn) {
        String normalized = fieldOrColumn.toLowerCase(Locale.ROOT);
        if (column.name().equalsIgnoreCase(normalized)) {
            return true;
        }
        return column.leafField().getName().equalsIgnoreCase(normalized);
    }

    public T newEntity() {
        try {
            return this.entityConstructor.newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate entity " + this.entityType.getName(), e);
        }
    }

    public Object newRelationElement(RelationDef relation) {
        try {
            return relation.elementConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate relation element for field " + relation.field().getName(), e);
        }
    }

    public ID idOf(T entity) {
        Object value = readColumnValue(entity, this.idColumn);
        return this.idType.cast(value);
    }

    public Column resolveColumn(String fieldOrColumn) {
        if (fieldOrColumn == null || fieldOrColumn.isBlank()) {
            throw new IllegalArgumentException("Sort field cannot be blank");
        }

        if (matchesColumn(this.idColumn, fieldOrColumn)) {
            return this.idColumn;
        }

        Optional<Column> resolved = this.columns.stream()
                .filter(column -> matchesColumn(column, fieldOrColumn))
                .findFirst();
        return resolved.orElseThrow(() -> new IllegalArgumentException(
                "Unknown sortable field '" + fieldOrColumn + "' for " + this.entityType.getSimpleName()
        ));
    }

    public Object readColumnRawValue(T entity, String fieldOrColumn) {
        Column column = resolveColumn(fieldOrColumn);
        return readColumnValue(entity, column);
    }

    public Object readColumnValue(T entity, Column column) {
        if (column.rootHandle() == null) {
            return column.leafHandle().get(entity);
        }
        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) return null;
        return column.leafHandle().get(embedded);
    }

    public void writeColumnValue(T entity, Column column, Object value) {
        if (column.rootHandle() == null) {
            column.leafHandle().set(entity, value);
            return;
        }

        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) {
            try {
                embedded = column.rootConstructor().newInstance();
            } catch (Exception e) {
                throw new RuntimeException("Unable to instantiate embedded object for field " + column.rootField().getName(), e);
            }
            column.rootHandle().set(entity, embedded);
        }
        column.leafHandle().set(embedded, value);
    }

    public Object readRelationField(T entity, RelationDef relation) {
        return relation.collectionHandle().get(entity);
    }

    public void writeRelationField(T entity, RelationDef relation, Object value) {
        relation.collectionHandle().set(entity, value);
    }

    public Object readRelationColumnValue(Object element, RelationColumn column) {
        return column.handle().get(element);
    }

    public void writeRelationColumnValue(Object element, RelationColumn column, Object value) {
        column.handle().set(element, value);
    }

    public void writeRankValue(T entity, RankDef rank, int value) {
        rank.handle().set(entity, value);
    }

    public List<BlobDef> blobs() {
        return blobs;
    }

    public Class<T> entityType() {
        return entityType;
    }

    public Class<ID> idType() {
        return idType;
    }

    public String namespace() {
        return namespace;
    }

    public Column idColumn() {
        return idColumn;
    }

    public List<Column> columns() {
        return columns;
    }

    public List<IndexDef> indexes() {
        return indexes;
    }


    public List<RelationDef> relations() {
        return relations;
    }

    public PersistedJsonMode jsonMode() {
        return jsonMode;
    }

    public List<RankDef> ranks() {
        return ranks;
    }

    public Optional<RankDef> rank(String name) {
        if (name == null || name.isBlank()) return Optional.empty();
        return this.ranks.stream().filter(r -> r.name().equalsIgnoreCase(name)).findFirst();
    }

    public List<RankDef> ranksMarkedForDeserialize() {
        return this.ranks.stream().filter(RankDef::loadOnDeserialize).toList();
    }
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.NoPersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlob;
import fr.ibrakash.helper.persistence.entity.PersistedBlobKind;
import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import fr.ibrakash.helper.persistence.entity.PersistedBlobTier;
import fr.ibrakash.helper.persistence.entity.PersistedColumn;
import fr.ibrakash.helper.persistence.entity.PersistedEmbedded;
import fr.ibrakash.helper.persistence.entity.PersistedEntity;
import fr.ibrakash.helper.persistence.entity.PersistedId;
import fr.ibrakash.helper.persistence.entity.PersistedIndex;
import fr.ibrakash.helper.persistence.entity.PersistedIndexes;
import fr.ibrakash.helper.persistence.entity.PersistedRelation;
import fr.ibrakash.helper.persistence.entity.PersistedJson;
import fr.ibrakash.helper.persistence.entity.PersistedJsonMode;
import fr.ibrakash.helper.persistence.entity.PersistedRank;
import fr.ibrakash.helper.persistence.query.SortClause;
import fr.ibrakash.helper.persistence.query.SortDirection;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;

public final class EntityModel<T, ID> {

    private static final int MAX_INDEX_NAME_LENGTH = 63;

    public record Column(
            Field rootField,
            Field leafField,
            String name,
            Class<?> type,
            boolean nullable,
            String defaultValue,
            int length,
            boolean id,
            VarHandle rootHandle,
            VarHandle leafHandle,
            Constructor<?> rootConstructor
    ) {}

    public record IndexDef(String name, List<String> columns, boolean unique) {}

    public record RelationColumn(Field field, String name, Class<?> type, int length, VarHandle handle) {}

    public record RelationDef(
            Field field,
            VarHandle collectionHandle,
            Constructor<?> elementConstructor,
            String table,
            String joinColumn,
            String valueColumn,
            String orderColumn,
            Class<?> elementType,
            boolean simple,
            List<RelationColumn> objectColumns
    ) {}

    public record BlobDef(
            Field field,
            VarHandle handle,
            String name,
            Class<?> type,
            boolean nullable,
            PersistedBlobKind kind,
            PersistedBlobTier tier,
            int length,
            Class<? extends PersistedBlobSerializer<?>> serializerClass,
            PersistedBlobSerializer<Object> serializer,
            Constructor<?> binaryStorageConstructor
    ) {}

    public record RankDef(
            Field field,
            VarHandle handle,
            String name,
            List<SortClause> sorts,
            boolean loadOnDeserialize
    ) {}

    private final Class<T> entityType;
    private final Class<ID> idType;
    private final String namespace;
    private final Column idColumn;
    private final List<Column> columns;
    private final List<IndexDef> indexes;
    private final List<RelationDef> relations;
    private final List<BlobDef> blobs;
    private final Constructor<T> entityConstructor;
    private final PersistedJsonMode jsonMode;
    private final List<RankDef> ranks;

    private EntityModel(Class<T> entityType,
                        Class<ID> idType,
                        String namespace,
                        Column idColumn,
                        List<Column> columns,
                        List<IndexDef> indexes,
                        List<RelationDef> relations,
                        List<BlobDef> blobs,
                        Constructor<T> entityConstructor,
                        PersistedJsonMode jsonMode,
                        List<RankDef> ranks) {
        this.entityType = entityType;
        this.idType = idType;
        this.namespace = namespace;
        this.idColumn = idColumn;
        this.columns = columns;
        this.indexes = indexes;
        this.relations = relations;
        this.blobs = blobs;
        this.entityConstructor = entityConstructor;
        this.jsonMode = jsonMode;
        this.ranks = ranks;
    }

    public static <T, ID> EntityModel<T, ID> from(Class<T> entityType, Class<ID> idType) {
        Field idField = null;
        List<Column> cols = new ArrayList<>();
        List<RelationDef> relations = new ArrayList<>();
        List<BlobDef> blobs = new ArrayList<>();
        List<RankDef> ranks = new ArrayList<>();

        for (Field field : entityType.getDeclaredFields()) {
            field.setAccessible(true);

            PersistedId id = field.getAnnotation(PersistedId.class);
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            PersistedEmbedded embedded = field.getAnnotation(PersistedEmbedded.class);
            PersistedColumn col = field.getAnnotation(PersistedColumn.class);
            PersistedBlob blob = field.getAnnotation(PersistedBlob.class);
            PersistedRank rank = field.getAnnotation(PersistedRank.class);

            if (id != null) {
                if (idField != null) {
                    throw new IllegalArgumentException("Multiple @PersistedId fields in " + entityType.getName());
                }
                String name = id.value().isBlank() ? snake(field.getName()) : id.value();
                idField = field;
                cols.add(new Column(null, field, name, field.getType(), false, "", 36, true,
                        null, varHandle(field), null));
                continue;
            }

            if (relation != null) {
                continue;
            }

            if (rank != null) {
                int mod = field.getModifiers();
                if (!java.lang.reflect.Modifier.isTransient(mod)) {
                    throw new IllegalArgumentException("@PersistedRank field must be transient: " + entityType.getName() + "#" + field.getName());
                }
                ranks.add(new RankDef(field, varHandle(field), field.getName(), List.of(), rank.load_on_deserialize()));
                continue;
            }

            if (embedded != null) {
                cols.addAll(parseEmbedded(field, embedded));
                continue;
            }

            if (blob != null) {
                blobs.add(parseBlob(field, blob));
                continue;
            }

            if (col == null) {
                int mod = field.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || field.isSynthetic()) {
                    continue;
                }
                cols.add(new Column(null, field, snake(field.getName()), field.getType(), true, "", 255, false,
                        null, varHandle(field), null));
            } else {
                String name = col.value().isBlank() ? snake(field.getName()) : col.value();
                cols.add(new Column(null, field, name, field.getType(), col.nullable(), col.defaultValue(), col.length(), false,
                        null, varHandle(field), null));
            }
        }

        if (idField == null) {
            throw new IllegalArgumentException("Missing @PersistedId field in " + entityType.getName());
        }

        for (Field field : entityType.getDeclaredFields()) {
            PersistedRelation relation = field.getAnnotation(PersistedRelation.class);
            if (relation == null) continue;
            field.setAccessible(true);
            relations.add(parseRelation(field, relation, idField));
        }

        Column idCol = cols.stream().filter(Column::id).findFirst().orElseThrow();
        List<Column> nonId = cols.stream().filter(c -> !c.id()).toList();

        PersistedEntity entityAnn = entityType.getAnnotation(PersistedEntity.class);
        String namespace = entityAnn != null && !entityAnn.value().isBlank()
                ? entityAnn.value()
                : snake(entityType.getSimpleName());

        List<IndexDef> indexes = parseIndexes(entityType);

        List<SortClause> defaultSort = List.of(new SortClause(idCol.name(), SortDirection.ASC));
        List<RankDef> resolvedRanks = new ArrayList<>(ranks.size());
        for (RankDef rank : ranks) {
            PersistedRank ann = rank.field().getAnnotation(PersistedRank.class);
            List<SortClause> parsed = parseSortClauses(ann.sort_columns(), idCol, nonId);
            if (parsed.isEmpty()) parsed = defaultSort;
            resolvedRanks.add(new RankDef(rank.field(), rank.handle(), rank.name(), parsed, rank.loadOnDeserialize()));
        }

        PersistedJson persistedJson = entityType.getAnnotation(PersistedJson.class);
        PersistedJsonMode configured = persistedJson == null ? PersistedJsonMode.AUTO : persistedJson.mode();
        PersistedJsonMode jsonMode = configured == PersistedJsonMode.AUTO
                ? (resolvedRanks.isEmpty() ? PersistedJsonMode.LOAD_ON_DEMAND : PersistedJsonMode.LOAD_ALL)
                : configured;

        return new EntityModel<>(
                entityType,
                idType,
                namespace,
                idCol,
                nonId,
                indexes,
                relations,
                blobs,
                constructor(entityType),
                jsonMode,
                List.copyOf(resolvedRanks)
        );
    }

    private static List<Column> parseEmbedded(Field rootField, PersistedEmbedded embedded) {
        List<Column> out = new ArrayList<>();
        String prefix = embedded.prefix().isBlank() ? snake(rootField.getName()) + "_" : embedded.prefix();
        VarHandle rootHandle = varHandle(rootField);
        Constructor<?> rootConstructor = constructor(rootField.getType());

        for (Field nested : collectInstanceFields(rootField.getType())) {
            nested.setAccessible(true);
            int mod = nested.getModifiers();
            if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                continue;
            }

            PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
            String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
            boolean nullable = nestedCol == null || nestedCol.nullable();
            String defaultValue = nestedCol == null ? "" : nestedCol.defaultValue();
            int length = nestedCol == null ? 255 : nestedCol.length();
            out.add(new Column(rootField, nested, prefix + baseName, nested.getType(), nullable, defaultValue, length, false,
                    rootHandle, varHandle(nested), rootConstructor));
        }

        return out;
    }

    private static List<Field> collectInstanceFields(Class<?> type) {
        List<Field> fields = new ArrayList<>();
        Set<String> seenNames = new HashSet<>();

        for (Class<?> cursor = type; cursor != null && cursor != Object.class; cursor = cursor.getSuperclass()) {
            for (Field field : cursor.getDeclaredFields()) {
                if (!seenNames.add(field.getName())) {
                    continue;
                }
                fields.add(field);
            }
        }

        return fields;
    }

    private static RelationDef parseRelation(Field field, PersistedRelation relation, Field idField) {
        if (!(field.getGenericType() instanceof ParameterizedType pt)) {
            throw new IllegalArgumentException("@PersistedRelation field must be parameterized: " + field.getName());
        }

        Type raw = pt.getRawType();
        if (!(raw instanceof Class<?> rawClass) || !java.util.Collection.class.isAssignableFrom(rawClass)) {
            throw new IllegalArgumentException("@PersistedRelation currently supports Collection/List/Set only: " + field.getName());
        }

        Type elementTypeArg = pt.getActualTypeArguments()[0];
        if (!(elementTypeArg instanceof Class<?> elementType)) {
            throw new IllegalArgumentException("Unsupported @PersistedRelation element type on " + field.getName());
        }

        String joinColumn = relation.joinColumn().isBlank()
                ? snake(idField.getName())
                : relation.joinColumn();
        String valueColumn = relation.valueColumn();
        String orderColumn = relation.orderColumn();

        boolean simple = EntityTypeMapper.isSupportedType(elementType);
        if (simple && valueColumn.isBlank()) {
            throw new IllegalArgumentException("@PersistedRelation valueColumn is required for simple element type on field " + field.getName());
        }

        List<RelationColumn> objectColumns = new ArrayList<>();
        Constructor<?> elementConstructor = null;
        if (!simple) {
            if (!valueColumn.isBlank()) {
                throw new IllegalArgumentException("@PersistedRelation valueColumn must be empty for object element type on field " + field.getName());
            }
            String prefix = relation.prefix().isBlank() ? snake(field.getName()) + "_" : relation.prefix();
            elementConstructor = constructor(elementType);
            for (Field nested : elementType.getDeclaredFields()) {
                nested.setAccessible(true);
                int mod = nested.getModifiers();
                if (java.lang.reflect.Modifier.isStatic(mod) || java.lang.reflect.Modifier.isTransient(mod) || nested.isSynthetic()) {
                    continue;
                }
                PersistedColumn nestedCol = nested.getAnnotation(PersistedColumn.class);
                String baseName = nestedCol == null || nestedCol.value().isBlank() ? snake(nested.getName()) : nestedCol.value();
                int length = nestedCol == null ? 255 : nestedCol.length();
                objectColumns.add(new RelationColumn(nested, prefix + baseName, nested.getType(), length, varHandle(nested)));
            }

            if (objectColumns.isEmpty()) {
                throw new IllegalArgumentException("@PersistedRelation object field has no serializable nested fields: " + field.getName());
            }
        }

        return new RelationDef(field, varHandle(field), elementConstructor, relation.table(), joinColumn, valueColumn, orderColumn,
                elementType, simple, objectColumns);
    }

    private static List<IndexDef> parseIndexes(Class<?> type) {
        List<IndexDef> out = new ArrayList<>();

        PersistedIndex one = type.getAnnotation(PersistedIndex.class);
        if (one != null) {
            out.add(toIndex(one, type.getSimpleName()));
        }

        PersistedIndexes many = type.getAnnotation(PersistedIndexes.class);
        if (many != null) {
            for (PersistedIndex index : many.value()) {
                out.add(toIndex(index, type.getSimpleName()));
            }
        }

        return out;
    }

    private static IndexDef toIndex(PersistedIndex ann, String entityName) {
        if (ann.columns().length == 0) {
            throw new IllegalArgumentException("@PersistedIndex on " + entityName + " has no columns");
        }
        String desired = ann.name().isBlank()
                ? "idx_" + snake(entityName) + "_" + String.join("_", ann.columns())
                : ann.name();
        return new IndexDef(shortenIndexName(desired), List.of(ann.columns()), ann.unique());
    }

    private static String shortenIndexName(String value) {
        String normalized = value.toLowerCase(Locale.ROOT);
        if (normalized.length() <= MAX_INDEX_NAME_LENGTH) {
            return normalized;
        }

        String hash = String.format(Locale.ROOT, "%08x", normalized.hashCode());
        int prefixLength = MAX_INDEX_NAME_LENGTH - 9;
        return normalized.substring(0, prefixLength) + "_" + hash;
    }

    private static String snake(String input) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c) && i > 0) {
                out.append('_');
            }
            out.append(Character.toLowerCase(c));
        }
        return out.toString();
    }

    private static VarHandle varHandle(Field field) {
        try {
            return MethodHandles.privateLookupIn(field.getDeclaringClass(), MethodHandles.lookup()).unreflectVarHandle(field);
        } catch (IllegalAccessException e) {
            throw new IllegalArgumentException("Unable to create VarHandle for field " + field.getDeclaringClass().getName() + "#" + field.getName(), e);
        }
    }

    @SuppressWarnings("unchecked")
    private static <V> Constructor<V> constructor(Class<?> type) {
        try {
            Constructor<V> constructor = (Constructor<V>) type.getDeclaredConstructor();
            constructor.setAccessible(true);
            return constructor;
        } catch (NoSuchMethodException e) {
            throw new IllegalArgumentException("Type requires a no-arg constructor: " + type.getName(), e);
        }
    }

    private static BlobDef parseBlob(Field field, PersistedBlob blob) {
        String name = blob.value().isBlank() ? snake(field.getName()) : blob.value();

        Class<? extends PersistedBlobSerializer<?>> serializerClass = blob.serializer();
        PersistedBlobSerializer<Object> serializer = PersistedBlobSerializers.resolve(field.getType(), field.getGenericType(), serializerClass);

        boolean hasExplicitSerializer = serializerClass != null && serializerClass != NoPersistedBlobSerializer.class;
        boolean binaryStorage = fr.ibrakash.helper.binary.BinaryStorage.class.isAssignableFrom(field.getType());
        boolean rawBytes = field.getType() == byte[].class;

        if (!binaryStorage && !rawBytes && serializer == null) {
            throw new IllegalArgumentException("@PersistedBlob field requires a serializer or BinaryStorage type: " + field.getName());
        }

        Constructor<?> storageCtor = null;
        if (binaryStorage) {
            storageCtor = constructor(field.getType());
            if (!hasExplicitSerializer && serializer == null) {
                serializer = null; // BinaryStorage handles serialization itself.
            }
        }

        return new BlobDef(
                field,
                varHandle(field),
                name,
                field.getType(),
                blob.nullable(),
                blob.kind(),
                blob.blobTier(),
                blob.length(),
                serializerClass,
                serializer,
                storageCtor
        );
    }

    private static List<SortClause> parseSortClauses(String[] values, Column idColumn, List<Column> columns) {
        if (values == null || values.length == 0) {
            return List.of();
        }
        List<SortClause> out = new ArrayList<>(values.length);
        for (String raw : values) {
            if (raw == null || raw.isBlank()) continue;
            String spec = raw.trim();
            String[] parts = spec.split("\\s+");
            String field = parts[0];
            SortDirection direction = SortDirection.ASC;
            if (parts.length > 1 && parts[1].equalsIgnoreCase("DESC")) {
                direction = SortDirection.DESC;
            }
            String resolved = resolveSortColumnName(field, idColumn, columns);
            out.add(new SortClause(resolved, direction));
        }
        return out;
    }

    private static String resolveSortColumnName(String fieldOrColumn, Column idColumn, List<Column> columns) {
        if (matchesColumn(idColumn, fieldOrColumn)) {
            return idColumn.name();
        }
        for (Column column : columns) {
            if (matchesColumn(column, fieldOrColumn)) {
                return column.name();
            }
        }
        throw new IllegalArgumentException("Unknown rank/sort field '" + fieldOrColumn + "'");
    }

    private static boolean matchesColumn(Column column, String fieldOrColumn) {
        String normalized = fieldOrColumn.toLowerCase(Locale.ROOT);
        if (column.name().equalsIgnoreCase(normalized)) {
            return true;
        }
        return column.leafField().getName().equalsIgnoreCase(normalized);
    }

    public T newEntity() {
        try {
            return this.entityConstructor.newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate entity " + this.entityType.getName(), e);
        }
    }

    public Object newRelationElement(RelationDef relation) {
        try {
            return relation.elementConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to instantiate relation element for field " + relation.field().getName(), e);
        }
    }

    public ID idOf(T entity) {
        Object value = readColumnValue(entity, this.idColumn);
        return this.idType.cast(value);
    }

    public Column resolveColumn(String fieldOrColumn) {
        if (fieldOrColumn == null || fieldOrColumn.isBlank()) {
            throw new IllegalArgumentException("Sort field cannot be blank");
        }

        if (matchesColumn(this.idColumn, fieldOrColumn)) {
            return this.idColumn;
        }

        Optional<Column> resolved = this.columns.stream()
                .filter(column -> matchesColumn(column, fieldOrColumn))
                .findFirst();
        return resolved.orElseThrow(() -> new IllegalArgumentException(
                "Unknown sortable field '" + fieldOrColumn + "' for " + this.entityType.getSimpleName()
        ));
    }

    public Object readColumnRawValue(T entity, String fieldOrColumn) {
        Column column = resolveColumn(fieldOrColumn);
        return readColumnValue(entity, column);
    }

    public Object readColumnValue(T entity, Column column) {
        if (column.rootHandle() == null) {
            return column.leafHandle().get(entity);
        }
        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) return null;
        return column.leafHandle().get(embedded);
    }

    public void writeColumnValue(T entity, Column column, Object value) {
        if (column.rootHandle() == null) {
            column.leafHandle().set(entity, value);
            return;
        }

        Object embedded = column.rootHandle().get(entity);
        if (embedded == null) {
            try {
                embedded = column.rootConstructor().newInstance();
            } catch (Exception e) {
                throw new RuntimeException("Unable to instantiate embedded object for field " + column.rootField().getName(), e);
            }
            column.rootHandle().set(entity, embedded);
        }
        column.leafHandle().set(embedded, value);
    }

    public Object readRelationField(T entity, RelationDef relation) {
        return relation.collectionHandle().get(entity);
    }

    public void writeRelationField(T entity, RelationDef relation, Object value) {
        relation.collectionHandle().set(entity, value);
    }

    public Object readRelationColumnValue(Object element, RelationColumn column) {
        return column.handle().get(element);
    }

    public void writeRelationColumnValue(Object element, RelationColumn column, Object value) {
        column.handle().set(element, value);
    }

    public void writeRankValue(T entity, RankDef rank, int value) {
        rank.handle().set(entity, value);
    }

    public List<BlobDef> blobs() {
        return blobs;
    }

    public Class<T> entityType() {
        return entityType;
    }

    public Class<ID> idType() {
        return idType;
    }

    public String namespace() {
        return namespace;
    }

    public Column idColumn() {
        return idColumn;
    }

    public List<Column> columns() {
        return columns;
    }

    public List<IndexDef> indexes() {
        return indexes;
    }


    public List<RelationDef> relations() {
        return relations;
    }

    public PersistedJsonMode jsonMode() {
        return jsonMode;
    }

    public List<RankDef> ranks() {
        return ranks;
    }

    public Optional<RankDef> rank(String name) {
        if (name == null || name.isBlank()) return Optional.empty();
        return this.ranks.stream().filter(r -> r.name().equalsIgnoreCase(name)).findFirst();
    }

    public List<RankDef> ranksMarkedForDeserialize() {
        return this.ranks.stream().filter(RankDef::loadOnDeserialize).toList();
    }
}

package fr.ibrakash.helper.persistence.entity.internal;

import fr.ibrakash.helper.persistence.entity.PersistedColumn;
import fr.ibrakash.helper.persistence.entity.PersistedEmbedded;
import fr.ibrakash.helper.persistence.entity.PersistedEntity;
import fr.ibrakash.helper.persistence.entity.PersistedId;
import org.junit.jupiter.api.Test;

import java.util.Set;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class EntityModelEmbeddedInheritanceTest {

    @Test
    void embeddedColumnsIncludeInheritedFieldsAndCanBeWritten() {
        EntityModel<TownShieldProfile, String> model = EntityModel.from(TownShieldProfile.class, String.class);

        Set<String> columns = model.columns().stream()
                .map(EntityModel.Column::name)
                .collect(Collectors.toSet());

        assertEquals(Set.of("shield_level", "shield_x", "shield_y", "shield_z"), columns);

        TownShieldProfile profile = new TownShieldProfile();
        EntityModel.Column x = model.resolveColumn("shield_x");
        EntityModel.Column level = model.resolveColumn("shield_level");

        model.writeColumnValue(profile, x, 128);
        model.writeColumnValue(profile, level, 3);

        assertNotNull(profile.shield);
        assertEquals(128, model.readColumnValue(profile, x));
        assertEquals(3, model.readColumnValue(profile, level));
    }

    @PersistedEntity("town_shield_profiles")
    static class TownShieldProfile {

        @PersistedId("id")
        private String id = "town:spawn";

        @PersistedEmbedded(prefix = "shield_")
        private ShieldDisplayData shield;
    }

    static class DisplayLocationData {

        @PersistedColumn("x")
        private int x;

        @PersistedColumn("y")
        private int y;

        @PersistedColumn("z")
        private int z;
    }

    static class ShieldDisplayData extends DisplayLocationData {

        @PersistedColumn("level")
        private int level;
    }
}

package fr.ibrakash.helper.example;

import fr.ibrakash.helper.example.sql.ExampleBadge;
import fr.ibrakash.helper.example.sql.ExampleData;
import fr.ibrakash.helper.example.sql.ExampleHomePoint;
import fr.ibrakash.helper.example.sql.ExampleRepository;
import fr.ibrakash.helper.example.sql.ExampleSettings;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.jetbrains.annotations.NotNull;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

/**
 * {@code /exampledata <sub> [args...]}
 *
 * <ul>
 *   <li>{@code create   <id> [displayName]}  — create a new profile</li>
 *   <li>{@code score    <id> <value>}         — set score</li>
 *   <li>{@code points   <id> <value>}         — set points</li>
 *   <li>{@code setting   <id> <notifications:true|false> <theme>}         — set settings</li>
 *   <li>{@code tag      <add|remove|list> <id> [tag]}              — manage tags</li>
 *   <li>{@code home     <add|remove|list> <id> [...]}}              — manage homes</li>
 *   <li>{@code blob     <badge|stat|note|raw> <id> ...}              — manage blobs</li>
 *   <li>{@code top      [limit]}              — show top N by score (default 10)</li>
 *   <li>{@code saveall}                       — bulk-save entire cache</li>
 *   <li>{@code save     <id>}                 — save one profile</li>
 *   <li>{@code delete   <id>}                 — delete a profile</li>
 *   <li>{@code bulkload <id1> [id2 ...]}      — bulk-load profiles into cache</li>
 *   <li>{@code info     <id>}                 — show a profile's current values</li>
 * </ul>
 */
public class ExampleDataCommand implements CommandExecutor, TabCompleter {

    private static final MiniMessage MM = MiniMessage.miniMessage();

    private static final List<String> SUBS = List.of(
            "create", "score", "points", "setting", "tag", "home", "blob",
            "top", "rank", "rankupdate", "rankbulk", "seed",
            "saveall", "save", "delete", "bulkload", "info"
    );

    private final ExamplePlugin plugin;

    public ExampleDataCommand(ExamplePlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public boolean onCommand(@NotNull CommandSender sender, @NotNull Command command,
                             @NotNull String label, @NotNull String @NotNull [] args) {

        if (!(sender instanceof Player player)) {
            sender.sendMessage("Only players can run this command.");
            return true;
        }

        if (args.length == 0) {
            sendHelp(player, label);
            return true;
        }

        ExampleRepository repo = plugin.getExampleRepository();
        String sub = args[0].toLowerCase(Locale.ROOT);

        switch (sub) {
            case "create" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " create <id> [displayName]"));
                    return true;
                }
                String id = args[1];
                String displayName = args.length >= 3
                        ? String.join(" ", Arrays.copyOfRange(args, 2, args.length))
                        : null;

                ExampleData data = ExampleData.of(id, displayName);
                repo.save(data);
                player.sendMessage(MM.deserialize("<green>Created profile <white>" + id));
            }

            // /exampledata score <id> <value>
            case "score" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " score <id> <value>"));
                    return true;
                }
                String id = args[1];
                long value;
                try {
                    value = Long.parseLong(args[2]);
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>Invalid number: <white>" + args[2]));
                    return true;
                }
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    data.setScore(value);
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Score updated for <white>" + id));
                });
            }

            // /exampledata points <id> <value>
            case "points" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " points <id> <value>"));
                    return true;
                }
                String id = args[1];
                int value;
                try {
                    value = Integer.parseInt(args[2]);
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>Invalid number: <white>" + args[2]));
                    return true;
                }
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    data.setPoints(value);
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Points updated for <white>" + id));
                });
            }

            // /exampledata setting <id> <notifications:true|false> <theme>
            case "setting" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " setting <id> <notifications:true|false> <theme>"));
                    return true;
                }
                String id = args[1];
                boolean notifications = Boolean.parseBoolean(args[2]);
                String theme = args[3];

                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    data.setSettings(new ExampleSettings(notifications, theme));
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Settings updated for <white>" + id));
                });
            }

            // /exampledata tag <add|remove|list> <id> [tag]
            case "tag" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag <add|remove|list> <id> [tag]"));
                    return true;
                }
                String action = args[1].toLowerCase(Locale.ROOT);
                String id = args[2];

                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }

                    switch (action) {
                        case "add" -> {
                            if (args.length < 4) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag add <id> <tag>"));
                                return;
                            }
                            String tag = args[3];
                            if (!data.getTags().contains(tag)) data.getTags().add(tag);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Tag added to <white>" + id));
                        }
                        case "remove" -> {
                            if (args.length < 4) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag remove <id> <tag>"));
                                return;
                            }
                            String tag = args[3];
                            data.getTags().remove(tag);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Tag removed from <white>" + id));
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Tags: <white>" + data.getTags()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag <add|remove|list> <id> [tag]"));
                    }
                });
            }

            // /exampledata home <add|remove|list> <id> [...]
            case "home" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home <add|remove|list> <id> [...]"));
                    return true;
                }
                String action = args[1].toLowerCase(Locale.ROOT);
                String id = args[2];

                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }

                    switch (action) {
                        case "add" -> {
                            if (args.length < 8) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home add <id> <name> <world> <x> <y> <z>"));
                                return;
                            }
                            String name = args[3];
                            String world = args[4];
                            try {
                                double x = Double.parseDouble(args[5]);
                                double y = Double.parseDouble(args[6]);
                                double z = Double.parseDouble(args[7]);
                                data.getHomes().add(new ExampleHomePoint(name, world, x, y, z));
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Home added for <white>" + id));
                            } catch (NumberFormatException e) {
                                player.sendMessage(MM.deserialize("<red>x/y/z must be numeric."));
                            }
                        }
                        case "remove" -> {
                            if (args.length < 4) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home remove <id> <name>"));
                                return;
                            }
                            String name = args[3];
                            data.getHomes().removeIf(h -> h.getName().equalsIgnoreCase(name));
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Home removed for <white>" + id));
                        }
                        case "list" -> {
                            if (data.getHomes().isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No homes for <white>" + id));
                                return;
                            }
                            player.sendMessage(MM.deserialize("<gold>Homes for <white>" + id));
                            for (ExampleHomePoint home : data.getHomes()) {
                                player.sendMessage(MM.deserialize("<gray>- <white>" + home.getName() + " <gray>@ <white>" + home.getWorld()
                                        + " <gray>(" + home.getX() + ", " + home.getY() + ", " + home.getZ() + ")"));
                            }
                        }
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home <add|remove|list> <id> [...]"));
                    }
                });
            }

            // /exampledata blob <badge|stat|note|raw> <id> [...]
            case "blob" -> {
                return handleBlob(label, args, repo, player);
            }

            // /exampledata top <cache|db|partial|dto|window|refresh> [limit]
            case "top" -> {
                String mode = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "cache";
                int limit = 10;
                if (args.length >= 3) {
                    try {
                        limit = Math.max(1, Integer.parseInt(args[2]));
                    } catch (NumberFormatException ignored) {
                    }
                }

                try {
                    switch (mode) {
                        case "cache" -> {
                            List<ExampleData> top = repo.getTopByScore(limit);
                            if (top.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in cache yet."));
                                return true;
                            }
                            player.sendMessage(MM.deserialize("<gold>Top " + top.size() + " profiles by score <gray>(cache)"));
                            for (int i = 0; i < top.size(); i++) {
                                ExampleData d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.getDisplayName()
                                        + " <gray>id=<white>" + d.getId()
                                        + " <gray>score=<white>" + d.getScore()
                                        + " <gray>pts=<white>" + d.getPoints()
                                        + " <gray>rankField=<white>" + d.getLeaderboardRank()));
                            }
                        }
                        case "db" -> {
                            List<ExampleData> top = repo.getTopProfiles();
                            if (top.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in storage."));
                                return true;
                            }
                            int cap = Math.min(limit, top.size());
                            player.sendMessage(MM.deserialize("<gold>Top " + cap + " profiles by score <gray>(db full columns)"));
                            for (int i = 0; i < cap; i++) {
                                ExampleData d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.getDisplayName()
                                        + " <gray>id=<white>" + d.getId()
                                        + " <gray>score=<white>" + d.getScore()
                                        + " <gray>pts=<white>" + d.getPoints()
                                        + " <gray>rankField=<white>" + d.getLeaderboardRank()));
                            }
                        }
                        case "partial" -> {
                            List<ExampleData> top = repo.getTop10Profiles();
                            int cap = Math.min(limit, top.size());
                            player.sendMessage(MM.deserialize("<gold>Top " + cap + " profiles <gray>(db partial columns)"));
                            for (int i = 0; i < cap; i++) {
                                ExampleData d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.getDisplayName()
                                        + " <gray>id=<white>" + d.getId()
                                        + " <gray>score=<white>" + d.getScore()));
                            }
                        }
                        case "dto" -> {
                            List<ExampleRepository.ExampleTopEntry> top = repo.getLeaderboardPage(limit);
                            if (top.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in cache yet."));
                                return true;
                            }
                            player.sendMessage(MM.deserialize("<gold>Top " + top.size() + " profiles <gray>(dto from cache)"));
                            for (int i = 0; i < top.size(); i++) {
                                ExampleRepository.ExampleTopEntry d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.displayName()
                                        + " <gray>id=<white>" + d.id()
                                        + " <gray>score=<white>" + d.score()));
                            }
                        }
                        case "window" -> {
                            List<ExampleRepository.ExampleTopEntry> page = repo.getTop10To20();
                            if (page.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in storage for window query."));
                                return true;
                            }
                            player.sendMessage(MM.deserialize("<gold>Window 10..20 <gray>(db query)"));
                            for (int i = 0; i < page.size(); i++) {
                                int absolute = 10 + i;
                                ExampleRepository.ExampleTopEntry d = page.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + absolute + " <white>" + d.displayName()
                                        + " <gray>id=<white>" + d.id()
                                        + " <gray>score=<white>" + d.score()));
                            }
                        }
                        case "refresh" -> {
                            List<ExampleData> top = repo.refreshLeaderboard(limit);
                            player.sendMessage(MM.deserialize("<green>Leaderboard refreshed from storage. Loaded <white>" + top.size() + "<green> entries."));
                        }
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " top <cache|db|partial|dto|window|refresh> [limit]"));
                    }
                } catch (Exception e) {
                    player.sendMessage(MM.deserialize("<red>Top query failed: <white>" + e.getMessage()));
                }
            }

            // /exampledata rank <id>
            case "rank" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " rank <id>"));
                    return true;
                }
                String id = args[1];
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    try {
                        int rank = repo.getLeaderboardPosition(data);
                        player.sendMessage(MM.deserialize("<green>Rank for <white>" + id + "<green>: <white>#" + rank));
                    } catch (Exception e) {
                        player.sendMessage(MM.deserialize("<red>Rank query failed: <white>" + e.getMessage()));
                    }
                });
            }

            // /exampledata rankupdate <id>
            case "rankupdate" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " rankupdate <id>"));
                    return true;
                }
                String id = args[1];
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    try {
                        repo.updateLeaderboardPosition(data);
                        player.sendMessage(MM.deserialize("<green>Updated rank field for <white>" + id + "<green>: <white>#" + data.getLeaderboardRank()));
                    } catch (Exception e) {
                        player.sendMessage(MM.deserialize("<red>Rank update failed: <white>" + e.getMessage()));
                    }
                });
            }

            // /exampledata rankbulk <id1> [id2 ...]
            case "rankbulk" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " rankbulk <id1> [id2 ...]"));
                    return true;
                }
                List<String> ids = Arrays.asList(Arrays.copyOfRange(args, 1, args.length));
                repo.bulkLoad(ids);
                List<ExampleData> loaded = ids.stream()
                        .map(repo::getIfPresent)
                        .flatMap(Optional::stream)
                        .toList();
                if (loaded.isEmpty()) {
                    player.sendMessage(MM.deserialize("<yellow>No matching cached profiles after bulk load."));
                    return true;
                }
                try {
                    repo.updateLeaderboardPositions(loaded);
                    player.sendMessage(MM.deserialize("<green>Bulk rank update done for <white>" + loaded.size() + "<green> profile(s)."));
                } catch (Exception e) {
                    player.sendMessage(MM.deserialize("<red>Bulk rank update failed: <white>" + e.getMessage()));
                }
            }

            // /exampledata seed <count>
            case "seed" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " seed <count>"));
                    return true;
                }
                int count;
                try {
                    count = Math.max(1, Integer.parseInt(args[1]));
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>Invalid number: <white>" + args[1]));
                    return true;
                }

                List<ExampleData> batch = new java.util.ArrayList<>(count);
                java.util.Random random = new java.util.Random();
                for (int i = 1; i <= count; i++) {
                    String id = "seed_" + i;
                    ExampleData data = ExampleData.of(id, "Seed " + i);
                    data.setScore(50L + random.nextLong(10_000));
                    data.setPoints(1 + random.nextInt(2_000));
                    batch.add(data);
                }
                repo.bulkSave(batch);
                player.sendMessage(MM.deserialize("<green>Seeded and saved <white>" + count + "<green> profile(s)."));
            }

            // /exampledata saveall
            case "saveall" -> {
                int size = repo.getCache().size();
                repo.saveAll();
                player.sendMessage(MM.deserialize("<green>Bulk-saved <white>" + size + " <green>profile(s)."));
            }

            // /exampledata save <id>
            case "save" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " save <id>"));
                    return true;
                }
                String id = args[1];
                repo.getIfPresent(id).ifPresentOrElse(data -> {
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Saved profile <white>" + id));
                }, () -> player.sendMessage(MM.deserialize("<red>Profile not cached: <white>" + id)));
            }

            // /exampledata delete <id>
            case "delete" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " delete <id>"));
                    return true;
                }
                String id = args[1];
                repo.delete(id);
                player.sendMessage(MM.deserialize("<red>Deleted profile <white>" + id));
            }

            // /exampledata bulkload <id1> [id2 ...]
            case "bulkload" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " bulkload <id1> [id2 ...]"));
                    return true;
                }
                List<String> ids = Arrays.asList(Arrays.copyOfRange(args, 1, args.length));
                repo.bulkLoad(ids);
                long loaded = ids.stream().filter(id -> repo.getIfPresent(id).isPresent()).count();
                player.sendMessage(MM.deserialize("<green>Bulk-loaded <white>" + loaded + "<green>/<white>" + ids.size()));
            }

            // /exampledata info <id>
            case "info" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " info <id>"));
                    return true;
                }
                String id = args[1];
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    player.sendMessage(MM.deserialize("<gold>Profile <white>" + id));
                    player.sendMessage(MM.deserialize("<gray>  display : <white>" + data.getDisplayName()));
                    player.sendMessage(MM.deserialize("<gray>  score   : <white>" + data.getScore()));
                    player.sendMessage(MM.deserialize("<gray>  points  : <white>" + data.getPoints()));
                    player.sendMessage(MM.deserialize("<gray>  settings: <white>notify=" + data.getSettings().isNotifications()
                            + " <gray>theme=<white>" + data.getSettings().getTheme()));
                    player.sendMessage(MM.deserialize("<gray>  tags    : <white>" + data.getTags()));
                    player.sendMessage(MM.deserialize("<gray>  homes   : <white>" + data.getHomes().size()));
                    player.sendMessage(MM.deserialize("<gray>  badges  : <white>" + data.getBadges()));
                    player.sendMessage(MM.deserialize("<gray>  stats   : <white>" + data.getStatBuckets()));
                    player.sendMessage(MM.deserialize("<gray>  notes   : <white>" + data.getNotes().getValue()));
                    player.sendMessage(MM.deserialize("<gray>  raw len : <white>" + data.getRawSnapshot().length));
                    player.sendMessage(MM.deserialize("<gray>  backend : <white>" + repo.backendType()));
                });
            }

            default -> sendHelp(player, label);
        }

        return true;
    }

    private boolean handleBlob(String label, String[] args, ExampleRepository repo, Player player) {
        if (args.length < 4) {
            player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob <badge|stat|note|raw> <id> ..."));
            return true;
        }

        String family = args[1].toLowerCase(Locale.ROOT);
        String id = args[2];

        return switch (family) {
            case "badge" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> <add|remove|list> [BADGE]"));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "add" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> add <BADGE>"));
                                return;
                            }
                            try {
                                ExampleBadge badge = ExampleBadge.valueOf(args[4].toUpperCase(Locale.ROOT));
                                if (!data.getBadges().contains(badge)) data.getBadges().add(badge);
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Badge added: <white>" + badge));
                            } catch (IllegalArgumentException e) {
                                player.sendMessage(MM.deserialize("<red>Unknown badge. Use: <white>" + Arrays.toString(ExampleBadge.values())));
                            }
                        }
                        case "remove" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> remove <BADGE>"));
                                return;
                            }
                            try {
                                ExampleBadge badge = ExampleBadge.valueOf(args[4].toUpperCase(Locale.ROOT));
                                data.getBadges().remove(badge);
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Badge removed: <white>" + badge));
                            } catch (IllegalArgumentException e) {
                                player.sendMessage(MM.deserialize("<red>Unknown badge. Use: <white>" + Arrays.toString(ExampleBadge.values())));
                            }
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Badges: <white>" + data.getBadges()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> <add|remove|list> [BADGE]"));
                    }
                });
                yield true;
            }
            case "stat" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> <put|remove|list> ..."));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "put" -> {
                            if (args.length < 6) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> put <key> <long>"));
                                return;
                            }
                            try {
                                long value = Long.parseLong(args[5]);
                                data.getStatBuckets().put(args[4], value);
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Blob stat updated."));
                            } catch (NumberFormatException e) {
                                player.sendMessage(MM.deserialize("<red>Invalid long: <white>" + args[5]));
                            }
                        }
                        case "remove" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> remove <key>"));
                                return;
                            }
                            data.getStatBuckets().remove(args[4]);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Blob stat removed."));
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Blob stats: <white>" + data.getStatBuckets()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> <put|remove|list> ..."));
                    }
                });
                yield true;
            }
            case "note" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> <add|remove|list> [text]"));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "add" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> add <text>"));
                                return;
                            }
                            String text = String.join(" ", Arrays.copyOfRange(args, 4, args.length));
                            data.getNotes().add(text);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Blob note added."));
                        }
                        case "remove" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> remove <text>"));
                                return;
                            }
                            String text = String.join(" ", Arrays.copyOfRange(args, 4, args.length));
                            data.getNotes().remove(text);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Blob note removed."));
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Blob notes: <white>" + data.getNotes().getValue()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> <add|remove|list> [text]"));
                    }
                });
                yield true;
            }
            case "raw" -> {
                if (args.length < 5) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob raw <id> <set|clear|len> [text]"));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "set" -> {
                            String text = String.join(" ", Arrays.copyOfRange(args, 4, args.length));
                            data.setRawSnapshot(text.getBytes(StandardCharsets.UTF_8));
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Raw blob bytes set (<white>" + data.getRawSnapshot().length + "<green>)."));
                        }
                        case "clear" -> {
                            data.setRawSnapshot(new byte[0]);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Raw blob cleared."));
                        }
                        case "len" -> player.sendMessage(MM.deserialize("<gray>Raw blob length: <white>" + data.getRawSnapshot().length));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob raw <id> <set|clear|len> [text]"));
                    }
                });
                yield true;
            }
            default -> {
                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob <badge|stat|note|raw> <id> ..."));
                yield true;
            }
        };
    }

    @Override
    public List<String> onTabComplete(@NotNull CommandSender sender, @NotNull Command command,
                                      @NotNull String label, @NotNull String @NotNull [] args) {
        if (args.length == 1) {
            String partial = args[0].toLowerCase(Locale.ROOT);
            return SUBS.stream().filter(s -> s.startsWith(partial)).toList();
        }
        if (args.length == 2 && "top".equalsIgnoreCase(args[0])) {
            return List.of("cache", "db", "partial", "dto", "window", "refresh").stream()
                    .filter(s -> s.startsWith(args[1].toLowerCase(Locale.ROOT)))
                    .toList();
        }
        return List.of();
    }

    private void sendHelp(Player player, String label) {
        player.sendMessage(MM.deserialize("<gold>ExampleData commands"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " create <id> [displayName]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " score <id> <value>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " points <id> <value>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " setting <id> <notifications:true|false> <theme>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " tag <add|remove|list> <id> [tag]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " home <add|remove|list> <id> [...]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " blob <badge|stat|note|raw> <id> ..."));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " top <cache|db|partial|dto|window|refresh> [limit]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " rank <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " rankupdate <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " rankbulk <id1> [id2 ...]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " seed <count>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " saveall"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " save <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " delete <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " bulkload <id1> [id2 ...]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " info <id>"));
    }
}

package fr.ibrakash.helper.example;

import fr.ibrakash.helper.example.sql.ExampleBadge;
import fr.ibrakash.helper.example.sql.ExampleData;
import fr.ibrakash.helper.example.sql.ExampleHomePoint;
import fr.ibrakash.helper.example.sql.ExampleRepository;
import fr.ibrakash.helper.example.sql.ExampleSettings;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.jetbrains.annotations.NotNull;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

/**
 * {@code /exampledata <sub> [args...]}
 *
 * <ul>
 *   <li>{@code create   <id> [displayName]}  — create a new profile</li>
 *   <li>{@code score    <id> <value>}         — set score</li>
 *   <li>{@code points   <id> <value>}         — set points</li>
 *   <li>{@code setting   <id> <notifications:true|false> <theme>}         — set settings</li>
 *   <li>{@code tag      <add|remove|list> <id> [tag]}              — manage tags</li>
 *   <li>{@code home     <add|remove|list> <id> [...]}}              — manage homes</li>
 *   <li>{@code blob     <badge|stat|note|raw> <id> ...}              — manage blobs</li>
 *   <li>{@code top      [limit]}              — show top N by score (default 10)</li>
 *   <li>{@code saveall}                       — bulk-save entire cache</li>
 *   <li>{@code save     <id>}                 — save one profile</li>
 *   <li>{@code delete   <id>}                 — delete a profile</li>
 *   <li>{@code bulkload <id1> [id2 ...]}      — bulk-load profiles into cache</li>
 *   <li>{@code info     <id>}                 — show a profile's current values</li>
 * </ul>
 */
public class ExampleDataCommand implements CommandExecutor, TabCompleter {

    private static final MiniMessage MM = MiniMessage.miniMessage();

    private static final List<String> SUBS = List.of(
            "create", "score", "points", "setting", "anchor", "tag", "home", "blob",
            "top", "rank", "rankupdate", "rankbulk", "seed",
            "saveall", "save", "delete", "bulkload", "info"
    );

    private final ExamplePlugin plugin;

    public ExampleDataCommand(ExamplePlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public boolean onCommand(@NotNull CommandSender sender, @NotNull Command command,
                             @NotNull String label, @NotNull String @NotNull [] args) {

        if (!(sender instanceof Player player)) {
            sender.sendMessage("Only players can run this command.");
            return true;
        }

        if (args.length == 0) {
            sendHelp(player, label);
            return true;
        }

        ExampleRepository repo = plugin.getExampleRepository();
        String sub = args[0].toLowerCase(Locale.ROOT);

        switch (sub) {
            case "create" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " create <id> [displayName]"));
                    return true;
                }
                String id = args[1];
                String displayName = args.length >= 3
                        ? String.join(" ", Arrays.copyOfRange(args, 2, args.length))
                        : null;

                ExampleData data = ExampleData.of(id, displayName);
                repo.save(data);
                player.sendMessage(MM.deserialize("<green>Created profile <white>" + id));
            }

            // /exampledata score <id> <value>
            case "score" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " score <id> <value>"));
                    return true;
                }
                String id = args[1];
                long value;
                try {
                    value = Long.parseLong(args[2]);
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>Invalid number: <white>" + args[2]));
                    return true;
                }
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    data.setScore(value);
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Score updated for <white>" + id));
                });
            }

            // /exampledata points <id> <value>
            case "points" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " points <id> <value>"));
                    return true;
                }
                String id = args[1];
                int value;
                try {
                    value = Integer.parseInt(args[2]);
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>Invalid number: <white>" + args[2]));
                    return true;
                }
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    data.setPoints(value);
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Points updated for <white>" + id));
                });
            }

            // /exampledata setting <id> <notifications:true|false> <theme>
            case "setting" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " setting <id> <notifications:true|false> <theme>"));
                    return true;
                }
                String id = args[1];
                boolean notifications = Boolean.parseBoolean(args[2]);
                String theme = args[3];

                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    ExampleSettings current = data.getSettings();
                    data.setSettings(new ExampleSettings(
                            notifications,
                            theme,
                            current.getX(),
                            current.getY(),
                            current.getZ()
                    ));
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Settings updated for <white>" + id));
                });
            }

            // /exampledata anchor <id> <x> <y> <z>
            case "anchor" -> {
                if (args.length < 5) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " anchor <id> <x> <y> <z>"));
                    return true;
                }
                String id = args[1];
                int x;
                int y;
                int z;
                try {
                    x = Integer.parseInt(args[2]);
                    y = Integer.parseInt(args[3]);
                    z = Integer.parseInt(args[4]);
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>x/y/z must be integers."));
                    return true;
                }

                final int fx = x;
                final int fy = y;
                final int fz = z;
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    data.getSettings().setX(fx);
                    data.getSettings().setY(fy);
                    data.getSettings().setZ(fz);
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Anchor updated for <white>" + id + "<green> -> <white>" + fx + "," + fy + "," + fz));
                });
            }

            // /exampledata tag <add|remove|list> <id> [tag]
            case "tag" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag <add|remove|list> <id> [tag]"));
                    return true;
                }
                String action = args[1].toLowerCase(Locale.ROOT);
                String id = args[2];

                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }

                    switch (action) {
                        case "add" -> {
                            if (args.length < 4) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag add <id> <tag>"));
                                return;
                            }
                            String tag = args[3];
                            if (!data.getTags().contains(tag)) data.getTags().add(tag);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Tag added to <white>" + id));
                        }
                        case "remove" -> {
                            if (args.length < 4) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag remove <id> <tag>"));
                                return;
                            }
                            String tag = args[3];
                            data.getTags().remove(tag);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Tag removed from <white>" + id));
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Tags: <white>" + data.getTags()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " tag <add|remove|list> <id> [tag]"));
                    }
                });
            }

            // /exampledata home <add|remove|list> <id> [...]
            case "home" -> {
                if (args.length < 3) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home <add|remove|list> <id> [...]"));
                    return true;
                }
                String action = args[1].toLowerCase(Locale.ROOT);
                String id = args[2];

                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }

                    switch (action) {
                        case "add" -> {
                            if (args.length < 8) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home add <id> <name> <world> <x> <y> <z>"));
                                return;
                            }
                            String name = args[3];
                            String world = args[4];
                            try {
                                double x = Double.parseDouble(args[5]);
                                double y = Double.parseDouble(args[6]);
                                double z = Double.parseDouble(args[7]);
                                data.getHomes().add(new ExampleHomePoint(name, world, x, y, z));
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Home added for <white>" + id));
                            } catch (NumberFormatException e) {
                                player.sendMessage(MM.deserialize("<red>x/y/z must be numeric."));
                            }
                        }
                        case "remove" -> {
                            if (args.length < 4) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home remove <id> <name>"));
                                return;
                            }
                            String name = args[3];
                            data.getHomes().removeIf(h -> h.getName().equalsIgnoreCase(name));
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Home removed for <white>" + id));
                        }
                        case "list" -> {
                            if (data.getHomes().isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No homes for <white>" + id));
                                return;
                            }
                            player.sendMessage(MM.deserialize("<gold>Homes for <white>" + id));
                            for (ExampleHomePoint home : data.getHomes()) {
                                player.sendMessage(MM.deserialize("<gray>- <white>" + home.getName() + " <gray>@ <white>" + home.getWorld()
                                        + " <gray>(" + home.getX() + ", " + home.getY() + ", " + home.getZ() + ")"));
                            }
                        }
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " home <add|remove|list> <id> [...]"));
                    }
                });
            }

            // /exampledata blob <badge|stat|note|raw> <id> [...]
            case "blob" -> {
                return handleBlob(label, args, repo, player);
            }

            // /exampledata top <cache|db|partial|dto|window|refresh> [limit]
            case "top" -> {
                String mode = args.length >= 2 ? args[1].toLowerCase(Locale.ROOT) : "cache";
                int limit = 10;
                if (args.length >= 3) {
                    try {
                        limit = Math.max(1, Integer.parseInt(args[2]));
                    } catch (NumberFormatException ignored) {
                    }
                }

                try {
                    switch (mode) {
                        case "cache" -> {
                            List<ExampleData> top = repo.getTopByScore(limit);
                            if (top.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in cache yet."));
                                return true;
                            }
                            player.sendMessage(MM.deserialize("<gold>Top " + top.size() + " profiles by score <gray>(cache)"));
                            for (int i = 0; i < top.size(); i++) {
                                ExampleData d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.getDisplayName()
                                        + " <gray>id=<white>" + d.getId()
                                        + " <gray>score=<white>" + d.getScore()
                                        + " <gray>pts=<white>" + d.getPoints()
                                        + " <gray>rankField=<white>" + d.getLeaderboardRank()));
                            }
                        }
                        case "db" -> {
                            List<ExampleData> top = repo.getTopProfiles();
                            if (top.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in storage."));
                                return true;
                            }
                            int cap = Math.min(limit, top.size());
                            player.sendMessage(MM.deserialize("<gold>Top " + cap + " profiles by score <gray>(db full columns)"));
                            for (int i = 0; i < cap; i++) {
                                ExampleData d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.getDisplayName()
                                        + " <gray>id=<white>" + d.getId()
                                        + " <gray>score=<white>" + d.getScore()
                                        + " <gray>pts=<white>" + d.getPoints()
                                        + " <gray>rankField=<white>" + d.getLeaderboardRank()));
                            }
                        }
                        case "partial" -> {
                            List<ExampleData> top = repo.getTop10Profiles();
                            int cap = Math.min(limit, top.size());
                            player.sendMessage(MM.deserialize("<gold>Top " + cap + " profiles <gray>(db partial columns)"));
                            for (int i = 0; i < cap; i++) {
                                ExampleData d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.getDisplayName()
                                        + " <gray>id=<white>" + d.getId()
                                        + " <gray>score=<white>" + d.getScore()));
                            }
                        }
                        case "dto" -> {
                            List<ExampleRepository.ExampleTopEntry> top = repo.getLeaderboardPage(limit);
                            if (top.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in cache yet."));
                                return true;
                            }
                            player.sendMessage(MM.deserialize("<gold>Top " + top.size() + " profiles <gray>(dto from cache)"));
                            for (int i = 0; i < top.size(); i++) {
                                ExampleRepository.ExampleTopEntry d = top.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + (i + 1) + " <white>" + d.displayName()
                                        + " <gray>id=<white>" + d.id()
                                        + " <gray>score=<white>" + d.score()));
                            }
                        }
                        case "window" -> {
                            List<ExampleRepository.ExampleTopEntry> page = repo.getTop10To20();
                            if (page.isEmpty()) {
                                player.sendMessage(MM.deserialize("<yellow>No profiles in storage for window query."));
                                return true;
                            }
                            player.sendMessage(MM.deserialize("<gold>Window 10..20 <gray>(db query)"));
                            for (int i = 0; i < page.size(); i++) {
                                int absolute = 10 + i;
                                ExampleRepository.ExampleTopEntry d = page.get(i);
                                player.sendMessage(MM.deserialize("<gray>#" + absolute + " <white>" + d.displayName()
                                        + " <gray>id=<white>" + d.id()
                                        + " <gray>score=<white>" + d.score()));
                            }
                        }
                        case "refresh" -> {
                            List<ExampleData> top = repo.refreshLeaderboard(limit);
                            player.sendMessage(MM.deserialize("<green>Leaderboard refreshed from storage. Loaded <white>" + top.size() + "<green> entries."));
                        }
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " top <cache|db|partial|dto|window|refresh> [limit]"));
                    }
                } catch (Exception e) {
                    player.sendMessage(MM.deserialize("<red>Top query failed: <white>" + e.getMessage()));
                }
            }

            // /exampledata rank <id>
            case "rank" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " rank <id>"));
                    return true;
                }
                String id = args[1];
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    try {
                        int rank = repo.getLeaderboardPosition(data);
                        player.sendMessage(MM.deserialize("<green>Rank for <white>" + id + "<green>: <white>#" + rank));
                    } catch (Exception e) {
                        player.sendMessage(MM.deserialize("<red>Rank query failed: <white>" + e.getMessage()));
                    }
                });
            }

            // /exampledata rankupdate <id>
            case "rankupdate" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " rankupdate <id>"));
                    return true;
                }
                String id = args[1];
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    try {
                        repo.updateLeaderboardPosition(data);
                        player.sendMessage(MM.deserialize("<green>Updated rank field for <white>" + id + "<green>: <white>#" + data.getLeaderboardRank()));
                    } catch (Exception e) {
                        player.sendMessage(MM.deserialize("<red>Rank update failed: <white>" + e.getMessage()));
                    }
                });
            }

            // /exampledata rankbulk <id1> [id2 ...]
            case "rankbulk" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " rankbulk <id1> [id2 ...]"));
                    return true;
                }
                List<String> ids = Arrays.asList(Arrays.copyOfRange(args, 1, args.length));
                repo.bulkLoad(ids);
                List<ExampleData> loaded = ids.stream()
                        .map(repo::getIfPresent)
                        .flatMap(Optional::stream)
                        .toList();
                if (loaded.isEmpty()) {
                    player.sendMessage(MM.deserialize("<yellow>No matching cached profiles after bulk load."));
                    return true;
                }
                try {
                    repo.updateLeaderboardPositions(loaded);
                    player.sendMessage(MM.deserialize("<green>Bulk rank update done for <white>" + loaded.size() + "<green> profile(s)."));
                } catch (Exception e) {
                    player.sendMessage(MM.deserialize("<red>Bulk rank update failed: <white>" + e.getMessage()));
                }
            }

            // /exampledata seed <count>
            case "seed" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " seed <count>"));
                    return true;
                }
                int count;
                try {
                    count = Math.max(1, Integer.parseInt(args[1]));
                } catch (NumberFormatException e) {
                    player.sendMessage(MM.deserialize("<red>Invalid number: <white>" + args[1]));
                    return true;
                }

                List<ExampleData> batch = new java.util.ArrayList<>(count);
                java.util.Random random = new java.util.Random();
                for (int i = 1; i <= count; i++) {
                    String id = "seed_" + i;
                    ExampleData data = ExampleData.of(id, "Seed " + i);
                    data.setScore(50L + random.nextLong(10_000));
                    data.setPoints(1 + random.nextInt(2_000));
                    batch.add(data);
                }
                repo.bulkSave(batch);
                player.sendMessage(MM.deserialize("<green>Seeded and saved <white>" + count + "<green> profile(s)."));
            }

            // /exampledata saveall
            case "saveall" -> {
                int size = repo.getCache().size();
                repo.saveAll();
                player.sendMessage(MM.deserialize("<green>Bulk-saved <white>" + size + " <green>profile(s)."));
            }

            // /exampledata save <id>
            case "save" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " save <id>"));
                    return true;
                }
                String id = args[1];
                repo.getIfPresent(id).ifPresentOrElse(data -> {
                    repo.save(data);
                    player.sendMessage(MM.deserialize("<green>Saved profile <white>" + id));
                }, () -> player.sendMessage(MM.deserialize("<red>Profile not cached: <white>" + id)));
            }

            // /exampledata delete <id>
            case "delete" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " delete <id>"));
                    return true;
                }
                String id = args[1];
                repo.delete(id);
                player.sendMessage(MM.deserialize("<red>Deleted profile <white>" + id));
            }

            // /exampledata bulkload <id1> [id2 ...]
            case "bulkload" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " bulkload <id1> [id2 ...]"));
                    return true;
                }
                List<String> ids = Arrays.asList(Arrays.copyOfRange(args, 1, args.length));
                repo.bulkLoad(ids);
                long loaded = ids.stream().filter(id -> repo.getIfPresent(id).isPresent()).count();
                player.sendMessage(MM.deserialize("<green>Bulk-loaded <white>" + loaded + "<green>/<white>" + ids.size()));
            }

            // /exampledata info <id>
            case "info" -> {
                if (args.length < 2) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " info <id>"));
                    return true;
                }
                String id = args[1];
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    player.sendMessage(MM.deserialize("<gold>Profile <white>" + id));
                    player.sendMessage(MM.deserialize("<gray>  display : <white>" + data.getDisplayName()));
                    player.sendMessage(MM.deserialize("<gray>  score   : <white>" + data.getScore()));
                    player.sendMessage(MM.deserialize("<gray>  points  : <white>" + data.getPoints()));
                    player.sendMessage(MM.deserialize("<gray>  settings: <white>notify=" + data.getSettings().isNotifications()
                            + " <gray>theme=<white>" + data.getSettings().getTheme()
                            + " <gray>anchor=<white>" + data.getSettings().getX() + "," + data.getSettings().getY() + "," + data.getSettings().getZ()));
                    player.sendMessage(MM.deserialize("<gray>  tags    : <white>" + data.getTags()));
                    player.sendMessage(MM.deserialize("<gray>  homes   : <white>" + data.getHomes().size()));
                    player.sendMessage(MM.deserialize("<gray>  badges  : <white>" + data.getBadges()));
                    player.sendMessage(MM.deserialize("<gray>  stats   : <white>" + data.getStatBuckets()));
                    player.sendMessage(MM.deserialize("<gray>  notes   : <white>" + data.getNotes().getValue()));
                    player.sendMessage(MM.deserialize("<gray>  raw len : <white>" + data.getRawSnapshot().length));
                    player.sendMessage(MM.deserialize("<gray>  backend : <white>" + repo.backendType()));
                });
            }

            default -> sendHelp(player, label);
        }

        return true;
    }

    private boolean handleBlob(String label, String[] args, ExampleRepository repo, Player player) {
        if (args.length < 4) {
            player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob <badge|stat|note|raw> <id> ..."));
            return true;
        }

        String family = args[1].toLowerCase(Locale.ROOT);
        String id = args[2];

        return switch (family) {
            case "badge" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> <add|remove|list> [BADGE]"));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "add" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> add <BADGE>"));
                                return;
                            }
                            try {
                                ExampleBadge badge = ExampleBadge.valueOf(args[4].toUpperCase(Locale.ROOT));
                                if (!data.getBadges().contains(badge)) data.getBadges().add(badge);
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Badge added: <white>" + badge));
                            } catch (IllegalArgumentException e) {
                                player.sendMessage(MM.deserialize("<red>Unknown badge. Use: <white>" + Arrays.toString(ExampleBadge.values())));
                            }
                        }
                        case "remove" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> remove <BADGE>"));
                                return;
                            }
                            try {
                                ExampleBadge badge = ExampleBadge.valueOf(args[4].toUpperCase(Locale.ROOT));
                                data.getBadges().remove(badge);
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Badge removed: <white>" + badge));
                            } catch (IllegalArgumentException e) {
                                player.sendMessage(MM.deserialize("<red>Unknown badge. Use: <white>" + Arrays.toString(ExampleBadge.values())));
                            }
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Badges: <white>" + data.getBadges()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob badge <id> <add|remove|list> [BADGE]"));
                    }
                });
                yield true;
            }
            case "stat" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> <put|remove|list> ..."));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "put" -> {
                            if (args.length < 6) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> put <key> <long>"));
                                return;
                            }
                            try {
                                long value = Long.parseLong(args[5]);
                                data.getStatBuckets().put(args[4], value);
                                repo.save(data);
                                player.sendMessage(MM.deserialize("<green>Blob stat updated."));
                            } catch (NumberFormatException e) {
                                player.sendMessage(MM.deserialize("<red>Invalid long: <white>" + args[5]));
                            }
                        }
                        case "remove" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> remove <key>"));
                                return;
                            }
                            data.getStatBuckets().remove(args[4]);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Blob stat removed."));
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Blob stats: <white>" + data.getStatBuckets()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob stat <id> <put|remove|list> ..."));
                    }
                });
                yield true;
            }
            case "note" -> {
                if (args.length < 4) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> <add|remove|list> [text]"));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "add" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> add <text>"));
                                return;
                            }
                            String text = String.join(" ", Arrays.copyOfRange(args, 4, args.length));
                            data.getNotes().add(text);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Blob note added."));
                        }
                        case "remove" -> {
                            if (args.length < 5) {
                                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> remove <text>"));
                                return;
                            }
                            String text = String.join(" ", Arrays.copyOfRange(args, 4, args.length));
                            data.getNotes().remove(text);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Blob note removed."));
                        }
                        case "list" -> player.sendMessage(MM.deserialize("<gray>Blob notes: <white>" + data.getNotes().getValue()));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob note <id> <add|remove|list> [text]"));
                    }
                });
                yield true;
            }
            case "raw" -> {
                if (args.length < 5) {
                    player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob raw <id> <set|clear|len> [text]"));
                    yield true;
                }
                String action = args[3].toLowerCase(Locale.ROOT);
                repo.getCached(id).thenAccept(data -> {
                    if (data == null) {
                        player.sendMessage(MM.deserialize("<red>No profile found: <white>" + id));
                        return;
                    }
                    switch (action) {
                        case "set" -> {
                            String text = String.join(" ", Arrays.copyOfRange(args, 4, args.length));
                            data.setRawSnapshot(text.getBytes(StandardCharsets.UTF_8));
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Raw blob bytes set (<white>" + data.getRawSnapshot().length + "<green>)."));
                        }
                        case "clear" -> {
                            data.setRawSnapshot(new byte[0]);
                            repo.save(data);
                            player.sendMessage(MM.deserialize("<green>Raw blob cleared."));
                        }
                        case "len" -> player.sendMessage(MM.deserialize("<gray>Raw blob length: <white>" + data.getRawSnapshot().length));
                        default -> player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob raw <id> <set|clear|len> [text]"));
                    }
                });
                yield true;
            }
            default -> {
                player.sendMessage(MM.deserialize("<red>Usage: /" + label + " blob <badge|stat|note|raw> <id> ..."));
                yield true;
            }
        };
    }

    @Override
    public List<String> onTabComplete(@NotNull CommandSender sender, @NotNull Command command,
                                      @NotNull String label, @NotNull String @NotNull [] args) {
        if (args.length == 1) {
            String partial = args[0].toLowerCase(Locale.ROOT);
            return SUBS.stream().filter(s -> s.startsWith(partial)).toList();
        }
        if (args.length == 2 && "top".equalsIgnoreCase(args[0])) {
            return List.of("cache", "db", "partial", "dto", "window", "refresh").stream()
                    .filter(s -> s.startsWith(args[1].toLowerCase(Locale.ROOT)))
                    .toList();
        }
        return List.of();
    }

    private void sendHelp(Player player, String label) {
        player.sendMessage(MM.deserialize("<gold>ExampleData commands"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " create <id> [displayName]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " score <id> <value>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " points <id> <value>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " setting <id> <notifications:true|false> <theme>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " anchor <id> <x> <y> <z>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " tag <add|remove|list> <id> [tag]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " home <add|remove|list> <id> [...]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " blob <badge|stat|note|raw> <id> ..."));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " top <cache|db|partial|dto|window|refresh> [limit]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " rank <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " rankupdate <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " rankbulk <id1> [id2 ...]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " seed <count>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " saveall"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " save <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " delete <id>"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " bulkload <id1> [id2 ...]"));
        player.sendMessage(MM.deserialize("<gray>  /" + label + " info <id>"));
    }
}

