package fr.ibrakash.helper.example.profile;

import fr.ibrakash.helper.persistence.PersistenceType;
import fr.ibrakash.helper.persistence.json.JsonRepository;
import fr.ibrakash.helper.utils.JsonUtil;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

/**
 * JSON implementation of {@link PlayerProfileRepository}.
 * Stores all profiles as {@code example_profiles.json} (UUID → {@link PlayerProfile}).
 */
public class JsonPlayerProfileRepository extends JsonRepository implements PlayerProfileRepository {

    private final Map<UUID, PlayerProfile> cache = new HashMap<>();

    @Override
    public void loadAll() {
        cache.clear();
        cache.putAll(JsonUtil.readFileMap(
            jsonFile("example_profiles"),
            HashMap::new, UUID.class, PlayerProfile.class
        ));
    }

    @Override
    public void saveAll() {
        JsonUtil.writeFile(jsonFile("example_profiles"), cache);
    }

    @Override
    public PlayerProfile getOrCreate(UUID playerId) {
        return cache.computeIfAbsent(playerId, id -> new PlayerProfile());
    }

    @Override
    public Optional<PlayerProfile> find(UUID playerId) {
        return Optional.ofNullable(cache.get(playerId));
    }

    @Override
    public void save(UUID playerId, PlayerProfile profile) {
        cache.put(playerId, profile);
        JsonUtil.writeFile(jsonFile("example_profiles"), cache);
    }

    @Override
    public void delete(UUID playerId) {
        cache.remove(playerId);
        JsonUtil.writeFile(jsonFile("example_profiles"), cache);
    }

    @Override
    public void close() { /* nothing to release for JSON */ }

    @Override
    public PersistenceType backendType() {
        return PersistenceType.JSON;
    }

    @Override
    public int cacheSize() {
        return cache.size();
    }
}

package fr.ibrakash.helper.example.profile;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.time.Instant;

/**
 * A concrete domain object stored via the persistence layer.
 *
 * <p>Jackson annotations make it serializable as JSON for the JSON persistence backend.
 * SQL backends map each field to a dedicated typed column.
 *
 * <p>Fields:
 * <ul>
 *   <li>{@code points}   – in-game currency / score</li>
 *   <li>{@code rank}     – player rank as a plain string (e.g. "VIP", "ADMIN")</li>
 *   <li>{@code lastSeen} – epoch seconds of last connection</li>
 * </ul>
 */
public class PlayerProfile {

    private int points;
    private String rank;
    private long lastSeen;

    /** No-arg constructor required by Jackson. */
    public PlayerProfile() {
        this.points = 0;
        this.rank = "DEFAULT";
        this.lastSeen = Instant.now().getEpochSecond();
    }

    @JsonCreator
    public PlayerProfile(
            @JsonProperty("points") int points,
            @JsonProperty("rank") String rank,
            @JsonProperty("lastSeen") long lastSeen
    ) {
        this.points = points;
        this.rank = rank == null ? "DEFAULT" : rank;
        this.lastSeen = lastSeen;
    }

    // -------------------------------------------------------------------------
    // Mutators
    // -------------------------------------------------------------------------

    public void addPoints(int amount) {
        this.points += amount;
    }

    public void removePoints(int amount) {
        this.points = Math.max(0, this.points - amount);
    }

    public void setRank(String rank) {
        this.rank = rank;
    }

    public void touchLastSeen() {
        this.lastSeen = Instant.now().getEpochSecond();
    }

    // -------------------------------------------------------------------------
    // Accessors
    // -------------------------------------------------------------------------

    @JsonProperty("points")
    public int getPoints() {
        return points;
    }

    @JsonProperty("rank")
    public String getRank() {
        return rank;
    }

    @JsonProperty("lastSeen")
    public long getLastSeen() {
        return lastSeen;
    }

    @Override
    public String toString() {
        return "PlayerProfile{points=" + points + ", rank='" + rank + "', lastSeen=" + lastSeen + "}";
    }
}

package fr.ibrakash.helper.example.profile;

import fr.ibrakash.helper.configuration.objects.database.ConfigPersistence;
import fr.ibrakash.helper.persistence.PersistenceEngine;
import fr.ibrakash.helper.persistence.PersistenceManager;
import fr.ibrakash.helper.persistence.PersistenceType;
import fr.ibrakash.helper.persistence.Repository;
import fr.ibrakash.helper.platform.KashAddon;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.Optional;
import java.util.UUID;

/**
 * Contract for persisting {@link PlayerProfile} objects.
 * Use {@link #create(KashAddon, ConfigPersistence)} to get the right implementation.
 */
public interface PlayerProfileRepository extends Repository {

    static PlayerProfileRepository create(KashAddon<JavaPlugin> addon, ConfigPersistence config) {
        PersistenceEngine engine = PersistenceManager.create(addon, config);
        PlayerProfileRepository repo = engine.type() == PersistenceType.SQL
                ? new SqlPlayerProfileRepository()
                : new JsonPlayerProfileRepository();
        repo.init(engine);
        repo.loadAll();
        return repo;
    }

    PlayerProfile getOrCreate(UUID playerId);

    Optional<PlayerProfile> find(UUID playerId);

    void save(UUID playerId, PlayerProfile profile);

    void delete(UUID playerId);

    void close();

    PersistenceType backendType();

    int cacheSize();
}

package fr.ibrakash.helper.example.profile;

import fr.ibrakash.helper.persistence.PersistenceType;
import fr.ibrakash.helper.persistence.sql.SqlRepository;
import fr.ibrakash.helper.sql.SqlDialectStatement;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

/**
 * SQL implementation of {@link PlayerProfileRepository}.
 *
 * <p>Table:
 * <pre>
 * example_profiles (
 *   uuid      VARCHAR(36) / TEXT    PRIMARY KEY,
 *   points    INT         / INTEGER NOT NULL DEFAULT 0,
 *   rank      VARCHAR(64) / TEXT    NOT NULL DEFAULT 'DEFAULT',
 *   last_seen BIGINT      / INTEGER NOT NULL DEFAULT 0
 * )
 * </pre>
 *
 * Statements:
 * <ul>
 *   <li>CREATE TABLE IF NOT EXISTS — SQLite override</li>
 *   <li>SELECT uuid, points, rank, last_seen — maps each row to a {@link PlayerProfile}</li>
 *   <li>UPSERT — MySQL/MariaDB: ON DUPLICATE KEY UPDATE
 *               PostgreSQL: ON CONFLICT DO UPDATE
 *               SQLite: INSERT OR REPLACE</li>
 *   <li>DELETE WHERE uuid = ?</li>
 * </ul>
 */
public class SqlPlayerProfileRepository extends SqlRepository implements PlayerProfileRepository {

    private static final SqlDialectStatement CREATE_TABLE = SqlDialectStatement
            .builder(
                "CREATE TABLE IF NOT EXISTS example_profiles (" +
                "  uuid      VARCHAR(36) PRIMARY KEY," +
                "  points    INT         NOT NULL DEFAULT 0," +
                "  rank      VARCHAR(64) NOT NULL DEFAULT 'DEFAULT'," +
                "  last_seen BIGINT      NOT NULL DEFAULT 0" +
                ")"
            )
            .sqlite(
                "CREATE TABLE IF NOT EXISTS example_profiles (" +
                "  uuid      TEXT    PRIMARY KEY," +
                "  points    INTEGER NOT NULL DEFAULT 0," +
                "  rank      TEXT    NOT NULL DEFAULT 'DEFAULT'," +
                "  last_seen INTEGER NOT NULL DEFAULT 0" +
                ")"
            )
            .build();

    private static final SqlDialectStatement SELECT_ALL = SqlDialectStatement
            .builder("SELECT uuid, points, rank, last_seen FROM example_profiles")
            .build();

    private static final SqlDialectStatement UPSERT = SqlDialectStatement
            .builder(
                "INSERT INTO example_profiles (uuid, points, rank, last_seen) VALUES (?, ?, ?, ?)" +
                " ON DUPLICATE KEY UPDATE points = VALUES(points), rank = VALUES(rank), last_seen = VALUES(last_seen)"
            )
            .postgresql(
                "INSERT INTO example_profiles (uuid, points, rank, last_seen) VALUES (?, ?, ?, ?)" +
                " ON CONFLICT (uuid) DO UPDATE SET" +
                "  points = EXCLUDED.points, rank = EXCLUDED.rank, last_seen = EXCLUDED.last_seen"
            )
            .sqlite(
                "INSERT OR REPLACE INTO example_profiles (uuid, points, rank, last_seen) VALUES (?, ?, ?, ?)"
            )
            .build();

    private static final SqlDialectStatement DELETE_ONE = SqlDialectStatement
            .builder("DELETE FROM example_profiles WHERE uuid = ?")
            .build();

    private final Map<UUID, PlayerProfile> cache = new HashMap<>();

    @Override
    protected void onCreate() {
        execute(stmt -> stmt.executeUpdate(CREATE_TABLE.resolve(driverType)));
    }

    @Override
    public void loadAll() {
        cache.clear();
        cache.putAll(query(SELECT_ALL.resolve(driverType), stmt -> {
            Map<UUID, PlayerProfile> result = new HashMap<>();
            var rs = stmt.executeQuery();
            while (rs.next()) {
                result.put(
                    UUID.fromString(rs.getString("uuid")),
                    new PlayerProfile(
                        rs.getInt   ("points"),
                        rs.getString("rank"),
                        rs.getLong  ("last_seen")
                    )
                );
            }
            return result;
        }));
    }

    @Override
    public void saveAll() {
        cache.forEach(this::save);
    }

    @Override
    public PlayerProfile getOrCreate(UUID playerId) {
        return cache.computeIfAbsent(playerId, id -> new PlayerProfile());
    }

    @Override
    public Optional<PlayerProfile> find(UUID playerId) {
        return Optional.ofNullable(cache.get(playerId));
    }

    @Override
    public void save(UUID playerId, PlayerProfile profile) {
        cache.put(playerId, profile);
        prepare(UPSERT.resolve(driverType), stmt -> {
            stmt.setString(1, playerId.toString());
            stmt.setInt   (2, profile.getPoints());
            stmt.setString(3, profile.getRank());
            stmt.setLong  (4, profile.getLastSeen());
            stmt.executeUpdate();
        });
    }

    @Override
    public void delete(UUID playerId) {
        cache.remove(playerId);
        prepare(DELETE_ONE.resolve(driverType), stmt -> {
            stmt.setString(1, playerId.toString());
            stmt.executeUpdate();
        });
    }

    @Override
    public void close() {
        database.shutdown();
    }

    @Override
    public PersistenceType backendType() {
        return PersistenceType.SQL;
    }

    @Override
    public int cacheSize() {
        return cache.size();
    }
}

package fr.ibrakash.helper.paper.serialization.itemstack;

import fr.ibrakash.helper.persistence.entity.PersistedBlobSerializer;
import org.bukkit.inventory.ItemStack;

public class DataItemStackArraySerializer implements PersistedBlobSerializer<ItemStack[]> {

    @Override
    public byte[] serialize(ItemStack[] value) {
        ItemStack[] items = value == null ? new ItemStack[0] : value;
        return ItemStack.serializeItemsAsBytes(items);
    }

    @Override
    public ItemStack[] deserialize(byte[] bytes) {
        if (bytes == null || bytes.length == 0) {
            return new ItemStack[0];
        }
        return ItemStack.deserializeItemsFromBytes(bytes);
    }

    @Override
    public ItemStack[] defaultValue() {
        return new ItemStack[0];
    }
}

